# Acceptance c3. c2 reached 2155-open and stopped on the header hash.
# That chooser's header glyph is not the zone chooser's icon. The recorded hash is the literal.
# c1 and c2 stay. Do not edit this file after it has run.
import json
from pathlib import Path

steps = json.loads(Path('work/scripts/accept_table_c2.json').read_text(encoding='utf-8'))
found = 0
for step in steps:
    if step['id'] == '2155-open':
        step['expect']['headerHash'] = '5a085475b10c089b8283a34f4248eb02b936adacb7327622fad6604ca214e51b'
        found += 1
if found != 1:
    raise SystemExit('2155-open count ' + str(found))
Path('work/scripts/accept_table_c3.json').write_text(json.dumps(steps, indent=2) + '\n', encoding='utf-8')

runner = Path('work/scripts/accept_runner_c2.mjs').read_text(encoding='utf-8')
repls = [
    ('accept_runner_c2.mjs', 'accept_runner_c3.mjs'),
    ('accept_table_c2.json', 'accept_table_c3.json'),
    ('accept-c2.jsonl', 'accept-c3.jsonl'),
    ('session-accept-c2-', 'session-accept-c3-'),
    ("tag: 'accept-c2-", "tag: 'accept-c3-"),
    ('import-inventory-c2.json', 'import-inventory-c3.json'),
    ('nvram-accept-c2-', 'nvram-accept-c3-'),
]
for old, new in repls:
    if runner.count(old) < 1:
        raise SystemExit('missing ' + old)
    runner = runner.replace(old, new)
note = '// c3: 2155-open header hash is the AF-ON glyph recorded by c2. c2 is kept.\n'
Path('work/scripts/accept_runner_c3.mjs').write_text(note + runner, encoding='utf-8')
print('ok', found)
